#include <iostream>
#include <cmath>
#include <vector>

bool calcular_lado(double area, double& destino) {
    if (!std::isfinite(area) || area < 0.0 || area > 100.0) {
        return false;
    }
    const double lado = std::sqrt(area);
    destino = lado;
    return true;
}

int main() {
    std::vector<double> areas{16.0, 1.0, 6.25, 100.0, -0.5, 100.5};
    const std::vector<double> copia = areas;
    int validas{0};
    int rechazadas{0};
    int hasta_dos_y_medio{0};
    for (const double area : areas) {
        double lado{-1.0};
        const bool aceptada = calcular_lado(area, lado);
        if (aceptada) {
            ++validas;
            if (lado <= 2.5) {
                ++hasta_dos_y_medio;
            }
        } else {
            ++rechazadas;
        }
    }
    bool conservados = areas.size() == copia.size();
    // El contrato limita el tamano a ocho: la conversion a int es segura.
    const int cantidad = static_cast<int>(areas.size());
    if (conservados) {
        for (int i{0}; i < cantidad; ++i) {
            if (areas.at(i) != copia.at(i)) {
                conservados = false;
            }
        }
    }
    std::cout << "Validas: " << validas << "\n"
              << "Rechazadas: " << rechazadas << "\n"
              << "Lados hasta 2.5: " << hasta_dos_y_medio << "\n"
              << "Datos conservados: " << conservados << "\n";
    return 0;
}

